/* ---------- 2. КАТАЛОГ МОДИФИКАТОРОВ ----------
   Формат записи повторяет stats.csv:
     id    — идентификатор из каталога (attr.strength, life.max_flat, ...)
     cat   — человекочитаемая категория
     nm    — название
     kind  — flat | inc | more | chance | flag  (тип сложения)
     stat  — во что пишем значение внутри движка
     r     — диапазон ролла [min,max] (тир аффикса)
     rar   — редкость: 0 обычный, 1 редкий, 2 эпический, 3 кейстоун
     nt    — пояснение для игрока
   Движок сам умеет складывать flat/inc/more, поэтому новые строки
   каталога добавляются одной строчкой без правки логики.
*/
const SKELETON_BASE_LIMIT=3, SKELETON_CARD_RANKS=3;
const MINION_BLINK_UNLOCK=40, MINION_RAID_UNLOCK=80;
const skeletonCardRank=()=>G&&G.bag
  ? Math.min(SKELETON_CARD_RANKS,Math.max(0,Math.round(G.bag.flat('minCount')))) : 0;
const skeletonAnimatorBonus=()=>G&&G.subclass==='animator'?Math.floor(G.lvl/20):0;
const skeletonDisplayCap=()=>SKELETON_BASE_LIMIT+SKELETON_CARD_RANKS+skeletonAnimatorBonus();

